   19	// The one surviving situation for invariant:NAKED_BESIDE_WALLED, after the QUAL-DEDUP merge: a naked
   20	// colony, a naked planet and a stationary fleet, each read at the bound and at zero. The cohort read
   21	// found accounts with planets at zero defence while a sibling held a real wall: the whole wall was
   22	// raised on the planet with the most to lose and the bare siblings were never reached. One login has
   23	// to give the bare planet the wall order the account already holds elsewhere, in the host's own yard.
   24	test('a login gives the bare sibling the wall the account already holds elsewhere', function (): void {
   25	    $situation = Situation::of($this)
   26	        ->levelEveryPlanet('robot_factory', 2)
   27	        ->levelEveryPlanet('shipyard', 4)
   28	        ->defence('rocket_launcher', 20)
   29	        ->stockEveryPlanet(20_000_000, 10_000_000, 5_000_000)
   30	        ->session();
   31	
   32	    $bare = Planet::query()->where('user_id', $this->currentUserId)->where('planet_type', 1)
   33	        ->whereKeyNot($this->currentPlanetId)->value('id');
   34	    $planet = app(PlanetServiceFactory::class)->make((int) $bare, true);
   35	
   36	    $situation->expectWork(AiWorkKind::QueueUnits);
   37	
   38	    // A short build may already be complete by the time the session's own clock has advanced to every
   39	    // intent, so the wall counts whether it is standing or still paid for in the yard.
   40	    expect(app(DefenseNeedEvaluator::class)->standingUnits($planet))->toBeGreaterThan(0, 'expected the wall on the bare sibling; ' . $situation->account());
   41	});
