   43	// QUAL-003's live shape (invariant:NAKED_BESIDE_WALLED, aspect:shipyard), the story the deleted
   44	// NakedColonyWallSituationTest held: the colony below the yard its wall waits on. The cohort read
   45	// found an account holding a wall on one planet while a young colony stood at zero defence: the wall
   46	// waits on a shipyard the colony does not have yet, and the account kept spending its yard elsewhere.
   47	// An account whose sibling already holds a wall has to bring the shipyard and then the wall to the
   48	// bare colony, instead of leaving it naked for as long as it plays.
   49	test('an account whose sibling holds a wall reaches the colony that has no shipyard yet', function (): void {
   50	    $before = Planet::query()->where('user_id', $this->currentUserId)->pluck('id')->all();
   51	
   52	    $situation = Situation::of($this)
   53	        ->level('robot_factory', 2)
   54	        ->level('shipyard', 4)
   55	        ->defence('rocket_launcher', 30)
   56	        ->colony()
   57	        ->stockEveryPlanet(20_000_000, 10_000_000, 5_000_000)
   58	        ->sessions(8, 30);
   59	
   60	    $colonyId = (int) Planet::query()->where('user_id', $this->currentUserId)->where('planet_type', 1)
   61	        ->whereNotIn('id', $before)->value('id');
   62	    $colony = app(PlanetServiceFactory::class)->make($colonyId, true);
   63	
   64	    expect(app(DefenseNeedEvaluator::class)->standingUnits($colony))->toBeGreaterThan(0, 'expected the wall on the colony that started without a shipyard; ' . $situation->account());
   65	});
   66	
   67	// The story the deleted NakedPlanetWallFirstTest held: the wall waits on a yard the bare colony does
   68	// not have, so its login has to go to that yard before any wall unit. The marker is the host's own
   69	// prerequisite list for the defence registry, not a facility this file names.
   70	test('a login beside a walled homeworld spends the bare colony on the yard its wall waits on', function (): void {
   71	    $before = Planet::query()->where('user_id', $this->currentUserId)->pluck('id')->all();
   72	
   73	    $situation = Situation::of($this)
   74	        ->level('robot_factory', 2)
   75	        ->level('shipyard', 4)
   76	        ->ships('small_cargo', 10)
   77	        ->defence('light_laser', 60)
   78	        ->colony()
   79	        ->stockEveryPlanet(50_000_000, 50_000_000, 50_000_000)
   80	        ->session();
   81	
   82	    $colonyId = (int) Planet::query()->where('user_id', $this->currentUserId)->where('planet_type', 1)
   83	        ->whereNotIn('id', $before)->value('id');
   84	    $ordered = BuildingQueue::query()->where('planet_id', $colonyId)->where('canceled', 0)
   85	        ->orderBy('id')->value('object_id');
   86	
   87	    expect($ordered)->not->toBeNull('the bare colony got no order this login; ' . $situation->account());
   88	
   89	    $prerequisites = [];
   90	    foreach (ObjectService::getDefenseObjects() as $defence) {
   91	        $prerequisites = [...$prerequisites, ...array_keys(ObjectService::getRecursiveRequirements($defence->machine_name))];
   92	    }
   93	
   94	    $orderedName = ObjectService::getObjectById((int) $ordered)->machine_name;
   95	    expect(in_array($orderedName, $prerequisites, true))->toBeTrue(
   96	        'the bare colony spent its login on ' . $orderedName . ', not on what its wall waits for; ' . $situation->account()
   97	    );
   98	});
