  100	// The story the deleted StationaryFleetWallSituationTest held: what a planet stands to lose is not only
  101	// the output that piles up while the account is away. A fleet left standing in orbit is worth to a
  102	// raider exactly what the pile is, so a wall sized on production alone leaves it uncovered. The plant
  103	// puts the idle fleet on a planet whose small wall already covers the mines, and the record must state
  104	// a need only once the fleet is there.
  105	test('an idle fleet raises what the planet stands to lose', function (): void {
  106	    $situation = Situation::of($this)
  107	        ->resources(1_000_000, 1_000_000, 1_000_000)
  108	        ->level('shipyard', 4)
  109	        ->defence('rocket_launcher', 200);
  110	
  111	    $player = $this->planetService->getPlayer();
  112	    $covered = app(DefenseNeedEvaluator::class)->evaluate($player, $this->planetService);
  113	
  114	    expect($covered)->toBeNull('the wall already covers production-only exposure; ' . $situation->account());
  115	
  116	    $situation->ships('light_fighter', 2_000);
  117	
  118	    $exposed = app(DefenseNeedEvaluator::class)->evaluate($player, $this->planetService);
  119	
  120	    expect($exposed)->toBeInstanceOf(DefenseNeed::class)
  121	        ->and($exposed->protectedValue)->toBeGreaterThan(0.0)
  122	        ->and($exposed->currentDefenseValue)->toBeGreaterThan(0.0);
  123	});
