  125	// The bound at zero of the fleet rule: the fleet only adds to the exposure, it is not what creates the
  126	// need. A planet whose own output is nothing still takes the file's floor, so an account is not left
  127	// naked because it has no fleet to protect.
  128	test('a planet with nothing standing in orbit still takes the doctrine floor', function (): void {
  129	    resolve(SettingsService::class)->set('economy_speed', 1);
  130	
  131	    Situation::of($this)
  132	        ->resources(1_000_000, 1_000_000, 1_000_000)
  133	        ->level('shipyard', 4)
  134	        ->level('metal_mine', 0)
  135	        ->level('crystal_mine', 0)
  136	        ->level('deuterium_synthesizer', 0);
  137	
  138	    $this->planetService->updateResourceProductionStats();
  139	
  140	    $need = app(DefenseNeedEvaluator::class)->evaluate($this->planetService->getPlayer(), $this->planetService);
  141	
  142	    expect($need)->toBeInstanceOf(DefenseNeed::class)
  143	        ->and($need->reason)->toBe('defense:need:minimum-deterrent');
  144	});
