  146	// The bound on the other side: a planet that already holds a wall is not the account's next wall order,
  147	// so one login serves the bare sibling instead of stacking yet another batch on the walled planet.
  148	test('a login does not spend its wall order on the planet that already holds one', function (): void {
  149	    $situation = Situation::of($this)
  150	        ->levelEveryPlanet('robot_factory', 2)
  151	        ->levelEveryPlanet('shipyard', 4)
  152	        ->defence('rocket_launcher', 20)
  153	        ->stockEveryPlanet(20_000_000, 10_000_000, 5_000_000)
  154	        ->session();
  155	
  156	    $home = app(PlanetServiceFactory::class)->make($this->currentPlanetId, true);
  157	    $situation->expectWork(AiWorkKind::QueueUnits);
  158	
  159	    expect(app(DefenseNeedEvaluator::class)->standingUnits($home))->toBe(20, 'expected the walled planet untouched while its sibling is bare; ' . $situation->account());
  160	});
  161	
  162	// The invariant counts the account, not the planet (player 51: one planet holding 1,496 units, others
  163	// naked), so a full day of the account's own logins must leave no sibling at zero defence.
  164	test('an account whose homeworld holds a wall leaves no sibling naked', function (): void {
  165	    $situation = Situation::of($this)
  166	        ->resources(50_000_000, 50_000_000, 50_000_000)
  167	        ->level('robot_factory', 2)
  168	        ->level('shipyard', 4)
  169	        ->ships('small_cargo', 10)
  170	        ->ships('light_laser', 60)
  171	        ->colony()
  172	        ->stockEveryPlanet(50_000_000, 50_000_000, 50_000_000);
  173	
  174	    $situation->day();
  175	
  176	    expect(nakedPlanets($this->currentUserId))->toBe([], 'these planets stay at zero defence; ' . $situation->account());
  177	});
