  192	    $situation->session();
  193	
  194	    foreach (nakedPlanets($this->currentUserId) as $planetId) {
  195	        $ordered = BuildingQueue::query()->where('planet_id', $planetId)->where('canceled', 0)->exists();
  196	        expect($ordered)->toBeTrue('the bare sibling got no order this login; ' . $situation->account());
  197	    }
  198	});
