  200	// The zero case of the rule: the invariant names a naked planet *beside a walled sibling*. A lone
  201	// planet has no sibling, so nothing hoists the wall for it -- it takes the ordinary floor.
  202	test('a one-planet account is walled without a sibling to point at', function (): void {
  203	    $situation = Situation::of($this)
  204	        ->resources(50_000_000, 50_000_000, 50_000_000)
  205	        ->level('robot_factory', 2)
  206	        ->level('shipyard', 4)
